/* @lc app=leetcode id=1766 lang=kotlin */
class Solution { fun getCoprimes(nums: IntArray, edges: Array<IntArray>): IntArray = Array(nums.size) { mutableListOf<Int>() }.let { adj -> edges.forEach { e -> adj[e[0]].apply { add(e[1]) }.run { adj[e[1]].add(e[0]) } }.run { IntArray(51) { -1 }.let { anc -> IntArray(51) { -1 }.let { ancDep -> IntArray(nums.size).let { res -> DeepRecursiveFunction<Triple<Int, Int, Int>, Unit> { (u, p, d) -> ( (1..50).filter { v -> anc[v] != -1 && (2..v).all { g -> v % g != 0 || nums[u] % g != 0 } }.maxByOrNull { ancDep[it] }?.let { res[u] = anc[it] } ?: run { res[u] = -1 } ).let { anc[nums[u]].let { oldAnc -> ancDep[nums[u]].let { oldDep -> run { anc[nums[u]] = u }.run { ancDep[nums[u]] = d }.run { adj[u].forEach { v -> if (v != p) callRecursive(Triple(v, u, d + 1)) } }.run { anc[nums[u]] = oldAnc }.run { ancDep[nums[u]] = oldDep } } } }.callRecursive(Triple(0, -1, 0)).let { res } } } } } }